1	using System.Drawing.Imaging;
2	using Microsoft.Extensions.Logging;
3	
4	namespace RuneshapePriceChecker.OCR;
5	
6	internal static class OcrPipeline
7	{
8	    private static ILogger? _pipelineLogger;
9	    public static void SetLogger(ILogger logger) => _pipelineLogger = logger;
10	
11	    public static Bitmap PrepareRowBitmap(Bitmap source, Rectangle? contentCrop, int rowY, int rowHeight)
12	    {
13	        var cropX = contentCrop?.X ?? 0;
14	        var cropW = contentCrop?.Width > 0
15	            ? Math.Min(contentCrop.Value.Width, source.Width - cropX)
16	            : source.Width;
17	        if (cropW <= 0) cropW = 200;
18	
19	        // 4px horizontal padding so character edges aren't clipped
20	        var padX = Math.Max(0, cropX - 4);
21	        var padW = Math.Min(cropW + 8, source.Width - padX);
22	
23	        var cropRect = new Rectangle(padX, rowY, padW, rowHeight);
24	        using var rowBitmap = source.Clone(cropRect, source.PixelFormat);
25	        using var upscaled = OcrImagePreprocessor.UpscaleForOcr(rowBitmap, 3);
26	        return OcrImagePreprocessor.AddWhiteBorder(upscaled, 2);
27	    }
28	    public static (int[] Ys, int[] Heights) DetectRowPositions(Bitmap source, Rectangle? contentCrop)
29	    {
30	        var srcRect = new Rectangle(0, 0, source.Width, source.Height);
31	        var data = source.LockBits(srcRect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
32	        try
33	        {
34	            var stride = data.Stride;
35	            var length = Math.Abs(stride) * source.Height;
36	            var bytes = new byte[length];
37	            System.Runtime.InteropServices.Marshal.Copy(data.Scan0, bytes, 0, length);
38	            return DetectRowPositions(bytes, source.Width, source.Height, stride, contentCrop);
39	        }
40	        finally
41	        {
42	            source.UnlockBits(data);
43	        }
44	    }
45	
46	    public static (int[] Ys, int[] Heights) DetectRowPositions(byte[] bytes, int width, int height, int stride, Rectangle? contentCrop)
47	    {
48	        var scanRegion = contentCrop ?? new Rectangle(0, 0, width, height);
49	        var scanX = scanRegion.X;
50	        var scanW = scanRegion.Width;
51	        var scanY = scanRegion.Y;
52	        var scanH = scanRegion.Height;
53	
54	        _pipelineLogger?.LogTrace("DetectRowPositions: region=({L},{T} {W}x{H})",
55	            scanX, scanY, scanW, scanH);
56	
57	        const int threshold = 2;
58	        const int minWidthPixels = 2;
59	
60	        var widthThreshold = Math.Max(minWidthPixels, (int)(scanW * 0.03));
61	
62	        var blackCounts = new int[scanH];
63	        for (var y = 0; y < scanH; y++)
64	        {
65	            var rowOffset = (scanY + y) * stride;
66	            var count = 0;
67	            for (var x = 0; x < scanW; x++)
68	            {
69	                var idx = rowOffset + ((scanX + x) * 3);
70	                if (bytes[idx] < 128)
71	                    count++;
72	            }
73	            blackCounts[y] = count >= widthThreshold ? count : 0;
74	        }
75	
76	        List<(int Start, int End)> regions = [];
77	        var inRow = false;
78	        var regionStart = 0;
79	
80	        for (var y = 0; y < scanH; y++)
81	        {
82	            if (blackCounts[y] >= threshold)
83	            {
84	                if (!inRow)
85	                {
86	                    regionStart = y;
87	                    inRow = true;
88	                }
89	            }
90	            else
91	            {
92	                if (inRow && y - regionStart >= 4)
93	                {
94	                    regions.Add((regionStart, y - 1));
95	                }
96	                inRow = false;
97	            }
98	        }
99	        if (inRow && scanH - regionStart >= 4)
100	            regions.Add((regionStart, scanH - 1));
101	
102	        if (regions.Count == 0)
103	            return ([], []);
104	
105	        // Merge regions less than 10px apart
106	        var merged = new List<(int Start, int End)> { regions[0] };
107	        for (var r = 1; r < regions.Count; r++)
108	        {
109	            var (Start, End) = merged[^1];
110	            if (regions[r].Start - End <= 10)
111	                merged[^1] = (Start, regions[r].End);
112	            else
113	                merged.Add(regions[r]);
114	        }
115	
116	        // Expand each merged band by 4px on each side (for descenders/ascenders)
117	        var result = new int[merged.Count];
118	        var heights = new int[merged.Count];
119	        for (var r = 0; r < merged.Count; r++)
120	        {
121	            var start = Math.Max(0, merged[r].Start - 4);
122	            var end = Math.Min(scanH - 1, merged[r].End + 4);
123	            result[r] = scanY + start;
124	            heights[r] = end - start + 1;
125	        }
126	
127	        _pipelineLogger?.LogTrace("DetectRowPositions: found {Count} rows, scanH={ScanH}", result.Length, scanH);
128	        return (result, heights);
129	    }
130	
131	
132	    public static void SaveRowDebugImage(Bitmap preprocessed, Rectangle? crop, int rowY, int rowHeight, int index, string dir)
133	    {
134	        var cropX = crop?.X ?? 0;
135	        var cropW = crop?.Width > 0
136	            ? Math.Min(crop.Value.Width, preprocessed.Width - cropX)
137	            : preprocessed.Width;
138	        if (cropW <= 0) return;
139	
140	        var rowRect = new Rectangle(cropX, rowY, cropW, rowHeight);
141	        if (rowRect.Height <= 0 || rowRect.Bottom > preprocessed.Height) return;
142	
143	        using var rowDbg = preprocessed.Clone(rowRect, preprocessed.PixelFormat);
144	        OcrImagePreprocessor.SavePng(rowDbg, Path.Combine(dir, $"Row{index + 1}.png"));
145	    }
146	
147	    public static void SaveRowOverlayDebugImage(Bitmap preprocessed, Rectangle? crop, int[] rowYs, int[] rowHeights, string dir)
148	    {
149	        var cropRect = crop ?? new Rectangle(0, 0, preprocessed.Width, preprocessed.Height);
150	        using var cropped = OcrImagePreprocessor.CropBitmap(preprocessed, cropRect);
151	        using var g = Graphics.FromImage(cropped);
152	        using var pen = new Pen(Color.FromArgb(180, 200, 50, 220), 2f);
153	
154	        for (var i = 0; i < rowYs.Length && i < rowHeights.Length; i++)
155	        {
156	            var localY = rowYs[i] - cropRect.Y;
157	            var h = rowHeights[i];
158	            if (localY >= 0 && localY + h <= cropped.Height)
159	                g.DrawRectangle(pen, 1, localY, cropped.Width - 2, h - 1);
160	        }
161	
162	        OcrImagePreprocessor.SavePng(cropped, Path.Combine(dir, "5 Rows.png"));
163	    }
164	}
