1	using System.Drawing.Imaging;
2	using Microsoft.Extensions.Logging;
3	using Windows.Globalization;
4	using Windows.Graphics.Imaging;
5	using Windows.Media.Ocr;
6	
7	// CA1416: all callers guard with OS build >= 17763
8	#pragma warning disable CA1416
9	
10	namespace RuneshapePriceChecker.OCR;
11	
12	internal sealed class WindowsOcrEngine
13	{
14	    private readonly OcrEngine _engine;
15	    internal string RequestedLanguageTag { get; }
16	    internal string ActualLanguageTag { get; }
17	    internal bool IsExactLanguageMatch { get; }
18	    private static readonly Dictionary<string, string> AppToWindowsLang = new(StringComparer.OrdinalIgnoreCase)
19	    {
20	        ["eng"] = "en-US",
21	        ["fra"] = "fr-FR",
22	        ["deu"] = "de-DE",
23	        ["spa"] = "es-ES",
24	        ["por"] = "pt-BR",
25	        ["rus"] = "ru-RU",
26	        ["tha"] = "th-TH",
27	        ["chi_tra"] = "zh-TW",
28	        ["kor"] = "ko-KR",
29	        ["jpn"] = "ja-JP",
30	    };
31	    public static string LanguageSettingsUri => "ms-settings:regionlanguage-adddisplaylanguage";
32	    public static void OpenLanguageSettings()
33	    {
34	        _ = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(LanguageSettingsUri)
35	        { UseShellExecute = true });
36	    }
37	
38	    public WindowsOcrEngine(string? appLanguage, ILogger? logger = null)
39	    {
40	        RequestedLanguageTag = appLanguage is not null && AppToWindowsLang.TryGetValue(appLanguage, out var requested)
41	            ? requested : "user-profile";
42	        if (appLanguage is not null && AppToWindowsLang.TryGetValue(appLanguage, out var winLang))
43	        {
44	            var selection = TryCreateFromLanguageOrFamily(winLang, appLanguage, logger);
45	            if (selection is not null)
46	            {
47	                _engine = selection.Value.Engine;
48	                ActualLanguageTag = selection.Value.ActualLanguageTag;
49	                IsExactLanguageMatch = selection.Value.IsExact;
50	                return;
51	            }
52	
53	            _engine = OcrEngine.TryCreateFromUserProfileLanguages()
54	                      ?? throw new InvalidOperationException("Windows OCR engine not available on this system.");
55	            ActualLanguageTag = "user-profile";
56	        }
57	        else
58	        {
59	            _engine = OcrEngine.TryCreateFromUserProfileLanguages()
60	                ?? throw new InvalidOperationException("No Windows OCR language available.");
61	            ActualLanguageTag = "user-profile";
62	        }
63	    }
64	
65	    internal static bool IsExactLanguageAvailable(string? appLanguage)
66	    {
67	        return appLanguage is not null && AppToWindowsLang.TryGetValue(appLanguage, out var winLang) &&
68	            OcrEngine.AvailableRecognizerLanguages.Any(language =>
69	                string.Equals(language.LanguageTag, winLang, StringComparison.OrdinalIgnoreCase));
70	    }
71	
72	    private static (OcrEngine Engine, string ActualLanguageTag, bool IsExact)? TryCreateFromLanguageOrFamily(string winLang, string appLang, ILogger? logger)
73	    {
74	        // Try the exact regional variant first
75	        var lang = new Language(winLang);
76	        var engine = OcrEngine.TryCreateFromLanguage(lang);
77	        if (engine is not null)
78	        {
79	            logger?.LogInformation("Windows OCR language pack for '{AppLang}' ({WinLang}) loaded successfully.",
80	                appLang, winLang);
81	            return (engine, winLang, true);
82	        }
83	
84	        // Exact variant not installed — try to find any installed pack matching the language family
85	        var familyPrefix = winLang[..2]; // "en", "fr", "de", etc.
86	        foreach (var available in OcrEngine.AvailableRecognizerLanguages)
87	        {
88	            var tag = available.LanguageTag;
89	            if (tag.StartsWith(familyPrefix, StringComparison.OrdinalIgnoreCase) && !string.Equals(tag, winLang, StringComparison.OrdinalIgnoreCase))
90	            {
91	                engine = OcrEngine.TryCreateFromLanguage(available);
92	                if (engine is not null)
93	                {
94	                    logger?.LogWarning(
95	                        "Windows OCR language pack for '{AppLang}' ({WinLang}) is not installed. " +
96	                        "Using '{Fallback}' ({FallbackTag}) as a compatible fallback. " +
97	                        "Consider installing the exact pack for best accuracy.",
98	                        appLang, winLang, available.NativeName, tag);
99	                    return (engine, tag, false);
100	                }
101	            }
102	        }
103	
104	        // No matching language pack found at all — fall back to user profile languages
105	        logger?.LogWarning(
106	            "Windows OCR language pack for '{AppLang}' ({WinLang}) is not installed. " +
107	            "Falling back to user profile languages. Install the language pack to improve OCR accuracy. " +
108	            "Press ⊞ Win and search for \"Language & region\" to install it.",
109	            appLang, winLang);
110	        var profileEngine = OcrEngine.TryCreateFromUserProfileLanguages();
111	        return profileEngine is null ? null : (profileEngine, "user-profile", false);
112	    }
113	
114	    public string Recognize(Bitmap bitmap, out int[] wordYPositions, int upscaleFactor, OcrPerfTiming? perf = null)
115	    {
116	        long? sw = perf is not null ? OcrPerfTiming.RecordStart(OcrPerfTiming.Slot.Recognize) : null;
117	
118	        try
119	        {
120	            using var ms = new MemoryStream();
121	            bitmap.Save(ms, ImageFormat.Bmp);
122	            ms.Position = 0;
123	            using var stream = ms.AsRandomAccessStream();
124	            var decoder = BitmapDecoder.CreateAsync(stream).GetAwaiter().GetResult();
125	            using var softwareBitmap = decoder.GetSoftwareBitmapAsync().GetAwaiter().GetResult();
126	
127	            var result = _engine.RecognizeAsync(softwareBitmap).GetAwaiter().GetResult();
128	            var positions = new List<int>(result.Lines.Count);
129	            var lineTexts = new string[result.Lines.Count];
130	            for (var i = 0; i < result.Lines.Count; i++)
131	            {
132	                var line = result.Lines[i];
133	                var words = new string[line.Words.Count];
134	                var ySum = 0.0;
135	                for (var w = 0; w < line.Words.Count; w++)
136	                {
137	                    words[w] = line.Words[w].Text;
138	                    ySum += line.Words[w].BoundingRect.Y;
139	                }
140	                lineTexts[i] = string.Join(" ", words);
141	
142	                var yTop = line.Words.Count > 0
143	                    ? (int)(((ySum / line.Words.Count) - 6) / upscaleFactor)
144	                    : 0;
145	                positions.Add(yTop);
146	            }
147	
148	            wordYPositions = [.. positions];
149	            return string.Join("\n", lineTexts);
150	        }
151	        finally
152	        {
153	            if (perf is not null && sw.HasValue)
154	                perf.RecordEnd(OcrPerfTiming.Slot.Recognize, sw.Value);
